describe('Form Submission and Stale Data Invalidation', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Adjust the URL to your form page
    });

    it('should successfully submit the form and invalidate stale data', () => {
        cy.intercept('POST', '/api/submit-form', {
            statusCode: 200,
            body: { success: true }
        }).as('formSubmit');

        cy.get('input[name="field1"]').type('Test Data');
        cy.get('input[name="field2"]').type('More Test Data');
        cy.get('button[type="submit"]').click();

        cy.wait('@formSubmit').its('response.statusCode').should('eq', 200);
        cy.get('.success-message').should('be.visible').and('contain', 'Form submitted successfully');

        // Check that stale data is invalidated
        cy.get('.data-display').should('not.contain', 'Stale Data');
    });

    it('should handle form submission failure gracefully', () => {
        cy.intercept('POST', '/api/submit-form', {
            statusCode: 500,
            body: { success: false, message: 'Submission failed' }
        }).as('formSubmitFail');

        cy.get('input[name="field1"]').type('Test Data');
        cy.get('input[name="field2"]').type('More Test Data');
        cy.get('button[type="submit"]').click();

        cy.wait('@formSubmitFail').its('response.statusCode').should('eq', 500);
        cy.get('.error-message').should('be.visible').and('contain', 'Submission failed');

        // Check that stale data is still present
        cy.get('.data-display').should('contain', 'Stale Data');
    });
});
